"""Ordered, nonoverlapping, inclusive field ranges.

Ranges carry both a selector group and a display position. They are normalized
in coordinate order before being put back into display order. This also makes
very large open-ended selections cheap: no list of individual indices is built.
"""
from dataclasses import dataclass
from .errors import Failure

MAX = (1 << 64) - 1


@dataclass
class Span:
    start: int
    end: int
    order: int = 0
    group: int = 0
    last_group: int = -1

    def __post_init__(self):
        if self.last_group < 0:
            self.last_group = self.group

    def copy(self, **kwargs):
        values = dict(start=self.start, end=self.end, order=self.order,
                      group=self.group, last_group=self.last_group)
        values.update(kwargs)
        return Span(**values)


def number(text, diagnostic=None):
    s = text[1:] if text.startswith('+') else text
    if not s or not s.isascii() or not s.isdigit():
        raise Failure('Failed to parse field: ' + (text if diagnostic is None else diagnostic))
    n = int(s)
    if n > MAX:
        raise Failure('Failed to parse field: ' + (text if diagnostic is None else diagnostic))
    return n


def parse_fields(text):
    result = []
    for order, field in enumerate(text.split(',')):
        if field.startswith('-'):
            lo, hi = 1, number(field[1:])
        elif field.endswith('-'):
            lo, hi = number(field[:-1]), MAX
        elif '-' in field:
            sides = field.split('-')
            if len(sides) != 2:
                raise Failure('Failed to parse field: ' + field)
            lo, hi = (number(side, field) for side in sides)
        else:
            lo = hi = number(field)
        if hi < lo:
            # An initial hyphen is an upper limit, rather than a two-sided range.
            if field.startswith('-') and hi == 0:
                raise Failure('Fields and positions are numbered from 1: 0')
            raise Failure(f'High end of range less than low end of range: {field}')
        if lo == 0 or hi == 0:
            raise Failure('Fields and positions are numbered from 1: 0')
        result.append(Span(lo, hi, order, order))
    return normalize(result)


def normalize(spans):
    if not spans:
        return []
    result = []
    for raw in sorted(spans, key=lambda s: (s.start, s.end, s.order)):
        s = raw.copy()
        if result:
            p = result[-1]
            if s.start <= p.end + 1:
                if p.group <= s.group <= p.last_group + 1:
                    p.end = max(p.end, s.end)
                    p.order = min(p.order, s.order)
                    p.last_group = max(p.last_group, s.last_group)
                    continue
                if s.start <= p.end:
                    s.start = p.end + 1
                    if s.start > s.end:
                        continue
        result.append(s)
    result.sort(key=lambda s: (s.order, s.start, s.end))
    return result


def subtract(spans, excludes):
    exclusions = []
    for s in sorted(excludes, key=lambda x: (x.start, x.end)):
        if exclusions and s.start <= exclusions[-1][1] + 1:
            exclusions[-1][1] = max(exclusions[-1][1], s.end)
        else:
            exclusions.append([s.start, s.end])
    result = []
    for span in spans:
        lo = span.start
        for a, b in exclusions:
            if b < lo:
                continue
            if a > span.end:
                break
            if a > lo:
                result.append(span.copy(start=lo, end=a - 1))
            lo = max(lo, b + 1)
            if lo > span.end:
                break
        if lo <= span.end:
            result.append(span.copy(start=lo))
    return result


def is_sorted(spans):
    return all(a.end < b.start for a, b in zip(spans, spans[1:]))


def indices(spans, size):
    for span in spans:
        yield from range(span.start - 1, min(span.end, size))
