"""Byte-string escapes accepted in literal separators."""

def unescape(text):
    data = text.encode('utf-8', 'surrogateescape')
    out = bytearray()
    i = 0
    simple = {ord('t'): 9, ord('n'): 10, ord('r'): 13, ord('0'): 0, 92: 92}
    while i < len(data):
        if data[i] == 92 and i + 1 < len(data):
            c = data[i + 1]
            if c in simple:
                out.append(simple[c]); i += 2; continue
            if c == ord('x') and i + 3 < len(data):
                h = data[i + 2:i + 4]
                if all(x in b'0123456789abcdefABCDEF' for x in h):
                    out.append(int(h, 16)); i += 4; continue
        out.append(data[i]); i += 1
    return bytes(out)
